import { useState, useRef } from 'react'
import { supabase } from '@lib/supabase'
import { Upload, X, Image as ImageIcon, AlertCircle } from 'lucide-react'
import toast from 'react-hot-toast'

const PhotoUploader = ({ userId, existingPhotos = [], onPhotosChange, maxPhotos = 5 }) => {
  const [uploading, setUploading] = useState(false)
  const [photos, setPhotos] = useState(existingPhotos)
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false)
  const [photoToDelete, setPhotoToDelete] = useState(null)
  const fileInputRef = useRef(null)

  const uploadPhoto = async (file) => {
    const fileExt = file.name.split('.').pop()
    const fileName = `${userId}/${Date.now()}.${fileExt}`
    const filePath = fileName

    const { error: uploadError } = await supabase.storage
      .from('photographer-portfolios')
      .upload(filePath, file, {
        cacheControl: '3600',
        upsert: false
      })

    if (uploadError) {
      throw uploadError
    }

    const { data: { publicUrl } } = supabase.storage
      .from('photographer-portfolios')
      .getPublicUrl(filePath)

    return publicUrl
  }

  const handleFileSelect = async (e) => {
    const files = Array.from(e.target.files || [])

    if (photos.length + files.length > maxPhotos) {
      toast.error(`Maximum ${maxPhotos} photos allowed`)
      return
    }

    // Validate file types and sizes
    const validFiles = files.filter(file => {
      const validTypes = ['image/jpeg', 'image/png']
      const maxSize = 10 * 1024 * 1024 // 10MB

      if (!validTypes.includes(file.type)) {
        toast.error(`${file.name}: Only JPEG and PNG files are allowed`)
        return false
      }

      if (file.size > maxSize) {
        toast.error(`${file.name}: File size must be less than 10MB`)
        return false
      }

      return true
    })

    if (validFiles.length === 0) return

    setUploading(true)
    const uploadPromises = validFiles.map(file => uploadPhoto(file))

    try {
      const uploadedUrls = await Promise.all(uploadPromises)
      const newPhotos = [...photos, ...uploadedUrls]
      setPhotos(newPhotos)
      onPhotosChange(newPhotos)
      toast.success(`${uploadedUrls.length} photo(s) uploaded successfully`)
    } catch (error) {
      console.error('Upload error:', error)
      toast.error('Failed to upload photos. Please try again.')
    } finally {
      setUploading(false)
      if (fileInputRef.current) {
        fileInputRef.current.value = ''
      }
    }
  }

  const handleDeleteClick = (photoUrl) => {
    setPhotoToDelete(photoUrl)
    setShowDeleteConfirm(true)
  }

  const confirmDelete = async () => {
    if (!photoToDelete) return

    try {
      // Extract file path from URL
      const urlParts = photoToDelete.split('/photographer-portfolios/')
      if (urlParts.length > 1) {
        const filePath = urlParts[1]
        await supabase.storage
          .from('photographer-portfolios')
          .remove([filePath])
      }

      const newPhotos = photos.filter(p => p !== photoToDelete)
      setPhotos(newPhotos)
      onPhotosChange(newPhotos)
      toast.success('Photo removed')
    } catch (error) {
      console.error('Error removing photo:', error)
      toast.error('Failed to remove photo')
    } finally {
      setShowDeleteConfirm(false)
      setPhotoToDelete(null)
    }
  }

  const cancelDelete = () => {
    setShowDeleteConfirm(false)
    setPhotoToDelete(null)
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <label className="block text-sm font-medium text-gray-700">
          Portfolio Photos ({photos.length}/{maxPhotos})
        </label>
        {photos.length < maxPhotos && (
          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            disabled={uploading}
            className="inline-flex items-center px-3 py-2 border border-transparent text-sm leading-4 font-medium rounded-md text-white bg-primary-600 hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50"
            aria-label="Upload photos"
          >
            <Upload className="w-4 h-4 mr-2" aria-hidden="true" />
            {uploading ? 'Uploading...' : 'Upload Photos'}
          </button>
        )}
      </div>

      <input
        ref={fileInputRef}
        type="file"
        accept="image/jpeg,image/png"
        multiple
        onChange={handleFileSelect}
        className="hidden"
        aria-label="Select photo files"
      />

      {/* Photo Grid */}
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-4">
        {photos.map((photo, index) => (
          <div key={photo} className="relative group aspect-square bg-gray-100 rounded-lg overflow-hidden">
            <img
              src={photo}
              alt={`Portfolio photo ${index + 1}`}
              className="w-full h-full object-cover"
            />
            <button
              type="button"
              onClick={() => handleDeleteClick(photo)}
              className="absolute top-2 right-2 p-1 bg-red-600 text-white rounded-full opacity-0 group-hover:opacity-100 transition-opacity focus:opacity-100 hover:bg-red-700"
              aria-label={`Remove photo ${index + 1}`}
            >
              <X className="w-4 h-4" aria-hidden="true" />
            </button>
          </div>
        ))}

        {/* Empty slots */}
        {Array.from({ length: maxPhotos - photos.length }).map((_, index) => (
          <div
            key={`empty-${index}`}
            className="aspect-square bg-gray-50 border-2 border-dashed border-gray-300 rounded-lg flex items-center justify-center"
          >
            <ImageIcon className="w-8 h-8 text-gray-400" aria-hidden="true" />
          </div>
        ))}
      </div>

      <p className="text-xs text-gray-500">
        Upload up to {maxPhotos} photos. JPEG or PNG format, max 10MB each.
      </p>

      {/* Delete Confirmation Modal */}
      {showDeleteConfirm && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg shadow-xl max-w-md w-full p-6 animate-in fade-in zoom-in duration-200">
            <div className="flex items-start mb-4">
              <div className="flex-shrink-0">
                <div className="w-12 h-12 rounded-full bg-red-100 flex items-center justify-center">
                  <AlertCircle className="w-6 h-6 text-red-600" aria-hidden="true" />
                </div>
              </div>
              <div className="ml-4">
                <h3 className="text-lg font-semibold text-gray-900 mb-1">
                  Delete Photo
                </h3>
                <p className="text-sm text-gray-600">
                  Are you sure you want to delete this photo? This action cannot be undone.
                </p>
              </div>
            </div>

            <div className="flex justify-end space-x-3 mt-6">
              <button
                type="button"
                onClick={cancelDelete}
                className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 transition-colors"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={confirmDelete}
                className="px-4 py-2 text-sm font-medium text-white bg-red-600 rounded-lg hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500 transition-colors"
              >
                Delete Photo
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

export default PhotoUploader